const allCurrentProducts = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a.sku-title, a[href*="/product/"], a[href*="/site/"]')).filter(a => a.closest('.sku-item, [data-testid="sku-item"], li[class*="sku"]'));
  // deduplicate by href
  const seen = new Set();
  const res = [];
  for (const a of links) {
    if (!seen.has(a.href) && a.textContent.trim().length > 10) {
      seen.add(a.href);
      res.push({
        title: a.textContent.trim(),
        href: a.href
      });
    }
  }
