const filterDetails = await browserjs(tabId, () => {
  function getGroupOptions(groupTitleRegex) {
    const fieldsets = Array.from(document.querySelectorAll('fieldset, [role="group"], .facet-group'));
    const matched = fieldsets.filter(f => {
      const legend = f.querySelector('legend, h2, h3, h4, .c-facet-group-title')?.textContent?.trim();
      return legend && groupTitleRegex.test(legend);
    });
    return matched.map(f => {
      const legend = f.querySelector('legend, h2, h3, h4, .c-facet-group-title')?.textContent?.trim();
      const showMoreBtn = f.querySelector('button[class*="show-more"], button[aria-expanded]');
      const options = Array.from(f.querySelectorAll('li, .c-facet-item, [class*="facet-option"]')).map(el => {
        const input = el.querySelector('input');
        const text = el.textContent?.trim();
        return {
          text,
          id: input?.id,
          name: input?.name,
          value: input?.value,
          checked: input?.checked
        };
      });
      return {
        legend,
        hasShowMore: !!showMoreBtn,
        showMoreText: showMoreBtn?.textContent?.trim(),
        options
      };
    });
  }

  // Also check sort options
  const sortSelect = document.querySelector('#sort-by-select, select[id*="sort"], [data-testid="sort-by-select"]');
  const sortOptions = sortSelect ? Array.from(sortSelect.options).map(o => ({ value: o.value, text: o.text, selected: o.selected })) : null;

  return {
    sortOptions,
    sortSelectId: sortSelect?.id,
    brand: getGroupOptions(/Brand/i),
    processor: getGroupOptions(/Processor Model/i),
    ram: getGroupOptions(/System Memory/i),
    resolution: getGroupOptions(/Screen Resolution/i),
    os: getGroupOptions(/Operating System/i)
  };
});

