const tabId = 248688717;

const modalOrList = await browserjs(tabId, () => {
  // Check if a modal or dialog opened
  const dialog = document.querySelector('[role="dialog"], .modal, .c-modal');
  if (dialog) {
    return {
      type: "dialog",
      title: dialog.querySelector('h1, h2, h3')?.textContent?.trim(),
      items: Array.from(dialog.querySelectorAll('label, [class*="option"]')).map(el => el.textContent?.trim()).filter(Boolean)
    };
  }

  // Otherwise check the resolution section elements
  const fieldsets = Array.from(document.querySelectorAll('fieldset, [role="group"], .facet-group'));
  const resGroup = fieldsets.find(f => {
    const legend = f.querySelector('legend, h2, h3, h4, .c-facet-group-title')?.textContent?.trim();
    return legend && /Screen Resolution/i.test(legend);
  });

  const allInputs = Array.from(resGroup?.querySelectorAll('input') || []).map(i => ({
    id: i.id,
    label: resGroup.querySelector(`label[for="${i.id}"]`)?.textContent?.trim()
  }));

  return { type: "fieldset", inputs: allInputs };
});

console.log(JSON.stringify(modalOrList, null, 2));

