const dialogDetails = await browserjs(tabId, () => {
  const dialog = document.querySelector('[role="dialog"], .modal, .c-modal');
  if (!dialog) return null;
  const buttons = Array.from(dialog.querySelectorAll('button')).map(b => ({
    text: b.textContent?.trim(),
    className: b.className,
    ariaLabel: b.getAttribute('aria-label')
  }));
  const options = Array.from(dialog.querySelectorAll('label, input')).map(el => ({
    tag: el.tagName,
    text: el.textContent?.trim(),
    id: el.id || el.getAttribute('for'),
    checked: el.checked
  }));
  return { buttons, options: options.filter(o => o.text && o.text.includes('1920 x 1080')) };
});

