const specs = await browserjs(tabId, () => {
  // Check if a modal or drawer opened
  const modal = document.querySelector('[role="dialog"], [aria-modal="true"], .c-modal, [class*="drawer"]');
  const context = modal || document;

  // Look for text in specs section
  const specsHeading = Array.from(context.querySelectorAll('h2, h3, h4')).find(h => /specs/i.test(h.textContent));

  // Let's get all key-value pairs
  // Best Buy often uses dt/dd or grid with labels and values or div pairs
  const pairs = [];

  // Try dt/dd
  const dts = context.querySelectorAll('dt');
  if (dts.length > 0) {
    dts.forEach(dt => {
      const dd = dt.nextElementSibling;
      pairs.push({ name: dt.textContent.trim(), value: dd?.textContent?.trim() });
    });
  }

  // Try brix or class-based structures
  const specItems = context.querySelectorAll('[class*="specification"], [class*="specRow"], [data-testid*="spec"]');

  return {
    hasModal: !!modal,
    modalTitle: modal?.querySelector('h1, h2, h3')?.textContent?.trim(),
    modalText: modal?.innerText?.slice(0, 5000),
    pairsCount: pairs.length,
    pairs: pairs.slice(0, 20)
  };
});

console.log(JSON.stringify(specs, null, 2));

