const tabId = 248688717;

await tool.navigate({
  tabId,
  url: "https://www.bestbuy.com/site/searchpage.jsp?id=pcat17071&qp=category_facet%3DAll+Laptops%7Epcmcat138500050001%5Escreenresolutionsv_facet%3DScreen+Resolution%7E1920+x+1080+%28Full+HD%29%5Esystemmemoryram_facet%3DSystem+Memory+%28RAM%29%7E16+gigabytes%5Ebrand_facet%3DBrand%7EHP&sp=Best-Selling&st=HP+laptop"
});

await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const matchingProducts = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('a.sku-title, a[href*="/product/"]')).map(a => ({
    title: a.textContent?.trim().replace(/\s+/g, ' '),
    href: a.href
  })).filter(a => a.title && (a.title.includes('HP') || a.title.includes('Laptop')));

  const seen = new Set();
  const unique = [];
  for (const item of items) {
    if (!seen.has(item.href)) {
      seen.add(item.href);
      unique.push(item);
    }
  }

  // Filter those that mention i7 / Core i7
  return unique.map((p, index) => ({
    overallRank: index + 1,
    title: p.title,
    href: p.href,
    isI7: /i7/i.test(p.title)
  }));
});

console.log("Matching products in Best-Selling order:");
console.log(JSON.stringify(matchingProducts, null, 2));

